class Solution { public: int maximumRequests(int n,vector<vector<int>>& requests){int answer=0,total=1<<requests.size();for(int mask=0;mask<total;++mask){int selected=__builtin_popcount((unsigned)mask);if(selected<=answer)continue;vector<int> balance(n);for(int i=0;i<(int)requests.size();++i)if(mask&(1<<i)){--balance[requests[i][0]];++balance[requests[i][1]];}if(all_of(balance.begin(),balance.end(),[](int value){return value==0;}))answer=selected;}return answer;} };
